/* =================================================================
   Atlas Badge — component styles
   All values reference semantic tokens only.
   No hex literals. No primitive tokens. No magic numbers.
   ================================================================= */

/* ── Base ─────────────────────────────────────────────────────── */

.badge {
  display: inline-flex;
  align-items: center;
  gap: var(--atlas-spacing-1);
  border-radius: var(--atlas-radius-full);
  font-family: var(--atlas-font-sans);
  font-weight: var(--atlas-font-weight-medium);
  white-space: nowrap;
  line-height: var(--atlas-line-height-tight); /* FIX BUG-025: was line-height: 1 */
  border: var(--atlas-border-width-1) solid transparent; /* reserves space; overridden per variant */
  box-sizing: border-box;
}

/* Square prop — tighter radius */
.square {
  border-radius: var(--atlas-radius-sm);
}

/* ── Sizes ────────────────────────────────────────────────────── */
/*
  Spec:
    sm: height=18px  padding-x=spacing-1_5(6px)   type=text-caption
    md: height=22px  padding-x=spacing-2(8px)      type=text-caption
    lg: height=26px  padding-x=spacing-2+0_5(10px) type=text-body-sm

  Heights are achieved via height + vertical centering (align-items already centers).
*/

.sm {
  height: calc(var(--atlas-spacing-4) + var(--atlas-spacing-0_5)); /* 18px */
  padding-inline: var(--atlas-spacing-1_5);
  font-size: var(--atlas-text-caption); /* font-size-xs = 12px */
}

.md {
  height: calc(var(--atlas-spacing-5) + var(--atlas-spacing-0_5)); /* 22px */
  padding-inline: var(--atlas-spacing-2);
  font-size: var(--atlas-text-caption);
}

.lg {
  /* 26px = spacing-6(24) + spacing-0_5(2) */
  height: calc(var(--atlas-spacing-6) + var(--atlas-spacing-0_5));
  padding-inline: calc(var(--atlas-spacing-2) + var(--atlas-spacing-0_5)); /* 10px */
  font-size: var(--atlas-text-body-sm); /* font-size-sm = 14px */
}

/* ── Variants ─────────────────────────────────────────────────── */

.default {
  background-color: var(--atlas-background-muted);
  color: var(--atlas-foreground);
}

.secondary {
  background-color: var(--atlas-background-subtle);
  color: var(--atlas-foreground);
}

/* FIX BUG-021: use --atlas-{intent}-foreground per spec; not --atlas-{intent} */
.success {
  background-color: var(--atlas-success-subtle);
  color: var(--atlas-success-foreground);
}

.warning {
  background-color: var(--atlas-warning-subtle);
  color: var(--atlas-warning-foreground);
}

.danger {
  background-color: var(--atlas-danger-subtle);
  color: var(--atlas-danger-foreground);
}

.info {
  background-color: var(--atlas-info-subtle);
  color: var(--atlas-info-foreground);
}

/* Outline — transparent bg, border = intent or border-strong */
.outline {
  background-color: transparent;
  color: var(--atlas-foreground);
  border-color: var(--atlas-border-strong);
}

/* Outline with intent — border and text adopt the intent color */
.outline.intentSuccess { color: var(--atlas-success); border-color: var(--atlas-success); }
.outline.intentWarning { color: var(--atlas-warning); border-color: var(--atlas-warning); }
.outline.intentDanger  { color: var(--atlas-danger);  border-color: var(--atlas-danger);  }
.outline.intentInfo    { color: var(--atlas-info);    border-color: var(--atlas-info);    }

/* ── Interactive hover states — FIX BUG-023 ───────────────────── */
/*
  Applied when onClick is present: badge renders with data-interactive attr.
  Hover backgrounds per spec.
*/

.badge[data-interactive] {
  cursor: pointer;
  /* reset button styles */
  appearance: none;
  text-decoration: none;
}

.badge[data-interactive]:focus-visible {
  outline: var(--atlas-border-width-2) solid var(--atlas-focus-ring);
  outline-offset: var(--atlas-spacing-0_5);
}

.badge.default[data-interactive]:hover   { background-color: var(--atlas-background-subtle); }
.badge.secondary[data-interactive]:hover { background-color: var(--atlas-background-muted); }
.badge.success[data-interactive]:hover   { background-color: var(--atlas-success-muted); }
.badge.warning[data-interactive]:hover   { background-color: var(--atlas-warning-muted); }
.badge.danger[data-interactive]:hover    { background-color: var(--atlas-danger-muted); }
.badge.info[data-interactive]:hover      { background-color: var(--atlas-info-muted); }
.badge.outline[data-interactive]:hover   { background-color: var(--atlas-background-subtle); }

/* ── Disabled ─────────────────────────────────────────────────── */

/* FIX BUG-022: add --atlas-foreground-disabled color override */
.disabled {
  opacity: var(--atlas-opacity-disabled);
  pointer-events: none;
  color: var(--atlas-foreground-disabled);
}

/* ── Dot ──────────────────────────────────────────────────────── */
/*
  6px circle — size-1_5 = 6px.
  Color inherits from parent `color` (currentColor) so it automatically
  matches the variant foreground without separate token lookups.
*/

.dot {
  width: var(--atlas-spacing-1_5);   /* 6px */
  height: var(--atlas-spacing-1_5);
  border-radius: var(--atlas-radius-full);
  background-color: currentColor;
  flex-shrink: 0;
}

/* ── Removable button ─────────────────────────────────────────── */
/*
  The × button is a proper <button> for keyboard + screen-reader access.
  It inherits the badge color; focus-visible ring is applied.
*/

.removeBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  cursor: pointer;
  color: currentColor;
  opacity: var(--atlas-opacity-hover); /* 0.9 — slightly subdued */
  font-size: 1em; /* scales with badge font-size */
  line-height: var(--atlas-line-height-tight); /* FIX BUG-025: was line-height: 1 */
  border-radius: var(--atlas-radius-sm);
  outline: none;
  flex-shrink: 0;
}

.removeBtn:hover {
  opacity: 1;
}

.removeBtn:focus-visible {
  outline: var(--atlas-border-width-2) solid var(--atlas-focus-ring);
  outline-offset: var(--atlas-spacing-0_5);
}

/* FIX BUG-074: coarse-pointer touch target expansion */
@media (pointer: coarse) {
  .removeBtn {
    min-width: var(--atlas-touch-min);   /* 44px */
    min-height: var(--atlas-touch-min);
  }
}

import figma from "@figma/code-connect"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"

figma.connect(
  Badge,
  "https://www.figma.com/design/cKYhfaHLCoyMHi9nKr63Ig/Atlas-Design-System?node-id=123-24",
  {
    props: {
      variant: figma.enum("Variant", {
        neutral: "default",
        primary: "secondary",
        success: "success",
        warning: "warning",
        danger:  "danger",
        info:    "info",
      }),
      size:     figma.enum("Size",  { sm: "sm", md: "md", lg: "lg" }),
      disabled: figma.enum("State", { disabled: true }),
    },
    example: ({ variant, size, disabled }) => (
      <Badge variant={variant} size={size} disabled={disabled}>
        Label
      </Badge>
    ),
  }
)

