/* =================================================================
   Atlas Badge — component styles
   All values reference semantic tokens only.
   No hex literals. No primitive tokens. No magic numbers.
   ================================================================= */

/* ── Base ─────────────────────────────────────────────────────── */

.badge {
  display: inline-flex;
  align-items: center;
  gap: var(--atlas-spacing-1);
  border-radius: var(--atlas-radius-full);
  font-family: var(--atlas-font-sans);
  font-weight: var(--atlas-font-weight-medium);
  white-space: nowrap;
  line-height: var(--atlas-line-height-tight); /* FIX BUG-025: was line-height: 1 */
  border: var(--atlas-border-width-1) solid transparent; /* reserves space; overridden per variant */
  box-sizing: border-box;
}

/* Square prop — tighter radius */
.square {
  border-radius: var(--atlas-radius-sm);
}

/* ── Sizes ────────────────────────────────────────────────────── */
/*
  Spec:
    sm: height=18px  padding-x=spacing-1_5(6px)   type=text-caption
    md: height=22px  padding-x=spacing-2(8px)      type=text-caption
    lg: height=26px  padding-x=spacing-2+0_5(10px) type=text-body-sm

  Heights are achieved via height + vertical centering (align-items already centers).
*/

.sm {
  height: calc(var(--atlas-spacing-4) + var(--atlas-spacing-0_5)); /* 18px */
  padding-inline: var(--atlas-spacing-1_5);
  font-size: var(--atlas-text-caption); /* font-size-xs = 12px */
}

.md {
  height: calc(var(--atlas-spacing-5) + var(--atlas-spacing-0_5)); /* 22px */
  padding-inline: var(--atlas-spacing-2);
  font-size: var(--atlas-text-caption);
}

.lg {
  /* 26px = spacing-6(24) + spacing-0_5(2) */
  height: calc(var(--atlas-spacing-6) + var(--atlas-spacing-0_5));
  padding-inline: calc(var(--atlas-spacing-2) + var(--atlas-spacing-0_5)); /* 10px */
  font-size: var(--atlas-text-body-sm); /* font-size-sm = 14px */
}

/* ── Variants ─────────────────────────────────────────────────── */

.default {
  background-color: var(--atlas-background-muted);
  color: var(--atlas-foreground);
}

.secondary {
  background-color: var(--atlas-background-subtle);
  color: var(--atlas-foreground);
}

/* FIX BUG-021: use --atlas-{intent}-foreground per spec; not --atlas-{intent} */
.success {
  background-color: var(--atlas-success-subtle);
  color: var(--atlas-success-foreground);
}

.warning {
  background-color: var(--atlas-warning-subtle);
  color: var(--atlas-warning-foreground);
}

.danger {
  background-color: var(--atlas-danger-subtle);
  color: var(--atlas-danger-foreground);
}

.info {
  background-color: var(--atlas-info-subtle);
  color: var(--atlas-info-foreground);
}

/* Outline — transparent bg, border = intent or border-strong */
.outline {
  background-color: transparent;
  color: var(--atlas-foreground);
  border-color: var(--atlas-border-strong);
