#!/usr/bin/env node
/**
 * atlas-sync — regenerates the atlas/ snapshot.
 *
 *   node scripts/atlas-sync.mjs                      # repo-derived refresh (no Figma)
 *   node scripts/atlas-sync.mjs --pull <file.json>   # merge a Figma MCP pull, stamp syncedAt
 *   node scripts/atlas-sync.mjs --check              # report only, write nothing (exit 1 on drift)
 *
 * The agent-facing half of this lives in .agents/skills/atlas-figma-sync/.
 * The pull file is produced by that skill from Figma MCP calls; its shape is
 * documented in references/mcp-pull.md. This script never talks to Figma and
 * never writes to Figma.
 */

import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const SRC = path.join(ROOT, "packages/ui-web/src")
const CC = path.join(ROOT, "packages/figma-sync/code-connect")
const TOKENS_CSS = path.join(ROOT, "packages/tokens/atlas.tokens.css")
const ATLAS = path.join(ROOT, "atlas")
const FILE_KEY = "cKYhfaHLCoyMHi9nKr63Ig"

/** Display order for index.md — tiers in AGENTS.md §4 order. */
const ORDER = [
  "Button", "Input", "Label", "Textarea", "Checkbox", "Switch", "Badge",
  "Alert", "Card", "Dialog", "Tabs", "NavBar",
]
/** Layout/platform groups; also rendered into a generated section of atlas/tokens.md. */
const LAYOUT_GROUPS = {
  "Typography families and letter spacing": ["font-sans", "font-arabic", "font-mono", "letter-spacing-"],
  "Layout grid": ["breakpoint-", "container-", "columns", "gutter", "margin"],
  "Dialog widths": ["dialog-"],
  "Safe area": ["safe-"],
  "Z-index": ["z-"],
}

/** Scale groups kept in tokens.json, in this order; file order within a group. */
const SCALE_PREFIXES = [
  "spacing-", "radius-", "font-size-", "text-", "font-weight-", "line-height-",
  "duration-", "easing-", "shadow-", "border-width-", "opacity-", "touch-",
  ...Object.values(LAYOUT_GROUPS).flat(),
]

/* ── args ───────────────────────────────────────────────── */

const args = process.argv.slice(2)
const flag = (n) => args.includes(n)
const opt = (n) => { const i = args.indexOf(n); return i === -1 ? null : args[i + 1] }
const CHECK = flag("--check")
const PULL_PATH = opt("--pull")

/* ── small helpers ──────────────────────────────────────── */

const read = (p) => fs.readFileSync(p, "utf8")
const uniqSort = (a) => [...new Set(a)].sort()
const today = () => new Date().toISOString()

